# ======================================================================
# ファイル名: app/utils/ai_image_crawler.py
# 役割:
#   - Selenium で対象サイト（config.pyの定義）を検索
#   - 商品ページから画像URLを収集
#   - 自己テスト用エントリーポイントを搭載
#   - 自己テスト結果を PNG 画像として保存（コンタクトシート + メタ情報）
# ======================================================================

import os
import io
import json
import math
import time
import logging
import datetime
from typing import List, Dict, Any, Optional
from urllib.parse import quote_plus
from pathlib import Path

import requests
from PIL import Image, ImageDraw, ImageFont

from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.chrome.options import Options
from selenium.webdriver.remote.webdriver import WebDriver
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.common.exceptions import TimeoutException

# Flask 経由でなく単体実行も可能にするための config 読み込み
try:
    from app.config.config import Config
except ImportError:
    raise ImportError("config.py が見つかりません。プロジェクトルートに config.py を配置してください。")

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s"
)


# =========================
# Crawler
# =========================
class CrawlerService:
    """対象サイトから商品画像URLを収集するクローラー"""

    def __init__(self, sites_config: Dict[str, Dict[str, Any]], headless: bool = True, wait_time: int = 25):
        self.sites_config = sites_config
        self.headless = headless
        self.wait_time = wait_time
        self.logger = logging.getLogger(self.__class__.__name__)

    def _init_driver(self) -> WebDriver:
        """Chrome WebDriver の初期化"""
        options = Options()
        if self.headless:
            options.add_argument("--headless=new")
        options.add_argument("--disable-gpu")
        options.add_argument("--no-sandbox")
        options.add_argument("--disable-dev-shm-usage")
        options.add_argument("--window-size=1200,1600")
        driver = webdriver.Chrome(options=options)
        driver.set_page_load_timeout(max(30, self.wait_time + 5))
        return driver

    def _accept_cookie_if_any(self, driver: WebDriver, selector: Optional[str]) -> None:
        if not selector:
            return
        try:
            btn = WebDriverWait(driver, 5).until(EC.element_to_be_clickable((By.CSS_SELECTOR, selector)))
            btn.click()
            self.logger.info("Cookie consent accepted.")
        except Exception:
            self.logger.info("No cookie consent (or not clickable).")

    def _extract_images_from_jsonld(self, json_text: str) -> List[str]:
        """JSON-LD（<script type='application/ld+json'>）から image を抽出"""
        out: List[str] = []
        try:
            data = json.loads(json_text)
        except Exception:
            return out

        # Product 直下 or @graph 配下に対応
        def _normalize_images(img_field) -> List[str]:
            if not img_field:
                return []
            if isinstance(img_field, str):
                return [img_field]
            if isinstance(img_field, list):
                urls = []
                for it in img_field:
                    if isinstance(it, str):
                        urls.append(it)
                    elif isinstance(it, dict):
                        if it.get("contentUrl"):
                            urls.append(it["contentUrl"])
                        elif "@id" in it:
                            urls.append(it["@id"])
                return urls
            if isinstance(img_field, dict):
                if img_field.get("contentUrl"):
                    return [img_field["contentUrl"]]
                if "@id" in img_field:
                    return [img_field["@id"]]
            return []

        images = []
        if isinstance(data, dict):
            if "image" in data:
                images = _normalize_images(data.get("image"))
            elif "@graph" in data and isinstance(data["@graph"], list):
                for node in data["@graph"]:
                    if not isinstance(node, dict):
                        continue
                    if node.get("@type") in ("Product", ["Product"]):
                        images = _normalize_images(node.get("image"))
                        if images:
                            break
        elif isinstance(data, list):
            # まれに配列で来る
            for node in data:
                if isinstance(node, dict) and node.get("@type") in ("Product", ["Product"]):
                    images = _normalize_images(node.get("image"))
                    if images:
                        break

        return [u for u in images if isinstance(u, str)]

    def search_and_collect_images(self, site_key: str, query: str, max_results: int = 6) -> List[str]:
        """指定サイトで検索し、商品ページから画像URLを取得"""
        if site_key not in self.sites_config:
            raise ValueError(f"Site '{site_key}' is not defined in configuration.")

        site_conf = self.sites_config[site_key]
        search_url = site_conf["search_url_template"].format(query=quote_plus(query))

        driver = self._init_driver()
        self.logger.info(f"Open search URL: {search_url}")
        driver.get(search_url)
        self._accept_cookie_if_any(driver, site_conf.get("cookie_accept_selector"))

        # 検索結果リンク要素の取得
        try:
            result_links = WebDriverWait(driver, self.wait_time).until(
                EC.presence_of_all_elements_located(
                    (By.CSS_SELECTOR, site_conf["search_result_link_selector"])
                )
            )
        except TimeoutException:
            self.logger.error("Search results not found within wait time.")
            driver.quit()
            return []

        product_links = []
        for link_elem in result_links[: max(1, max_results * 3)]:  # 多少多めに拾っておく
            href = link_elem.get_attribute("href")
            if href:
                product_links.append(href)

        self.logger.info(f"Candidate product links: {len(product_links)}")

        # 各商品ページから JSON-LD を読み取って画像を集める
        image_urls: List[str] = []
        for href in product_links[:max_results]:
            try:
                driver.execute_script("window.open(arguments[0], '_blank');", href)
                driver.switch_to.window(driver.window_handles[-1])
                self._accept_cookie_if_any(driver, site_conf.get("cookie_accept_selector"))

                # JSON-LD をすべて拾う（複数あるケースあり）
                scripts = driver.find_elements(By.CSS_SELECTOR, site_conf["structured_data_selector"])
                got = False
                for sc in scripts:
                    text = sc.get_attribute("innerText") or sc.get_attribute("innerHTML")
                    urls = self._extract_images_from_jsonld(text or "")
                    if urls:
                        image_urls.extend(urls)
                        got = True
                if not got:
                    self.logger.warning(f"No JSON-LD images on: {href}")

            except Exception as e:
                self.logger.warning(f"Fail on product page {href}: {e}")
            finally:
                # タブを閉じて検索結果に戻る
                if len(driver.window_handles) > 1:
                    driver.close()
                    driver.switch_to.window(driver.window_handles[0])

        driver.quit()

        # 重複除去
        deduped = list(dict.fromkeys(image_urls))
        self.logger.info(f"Collected image URLs: {len(deduped)}")
        return deduped


# =========================
# Self-test Report (PNG)
# =========================
def _fetch_image(url: str, timeout: int = 20, max_bytes: int = 5_000_000) -> Optional[Image.Image]:
    """URL から画像を取得（簡易サイズ制限つき）"""
    try:
        headers = {
            "User-Agent": (
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                "AppleWebKit/537.36 (KHTML, like Gecko) "
                "Chrome/123.0.0.0 Safari/537.36"
            )
        }
        r = requests.get(url, headers=headers, timeout=timeout, stream=True)
        r.raise_for_status()
        content = r.content if len(r.content) <= max_bytes else r.raw.read(max_bytes)
        img = Image.open(io.BytesIO(content)).convert("RGB")
        return img
    except Exception:
        return None


def _text_wrap(draw: ImageDraw.ImageDraw, text: str, font: ImageFont.ImageFont, max_width: int) -> List[str]:
    """簡易テキスト折り返し"""
    words = text.split()
    if not words:
        return [""]
    lines: List[str] = []
    cur = words[0]
    for w in words[1:]:
        if draw.textlength(cur + " " + w, font=font) <= max_width:
            cur += " " + w
        else:
            lines.append(cur)
            cur = w
    lines.append(cur)
    return lines


def save_selftest_report_png(
    outfile: Path,
    *,
    site: str,
    query: str,
    image_urls: List[str],
    thumb_cols: int = 3,
    thumb_size: int = 256,
) -> Path:
    """
    収集結果を 1 枚の PNG にまとめて保存（メタ情報 + サムネイル格子）
    """
    outfile.parent.mkdir(parents=True, exist_ok=True)

    # メタ情報描画用フォント（非依存でOKなデフォルト）
    try:
        font_title = ImageFont.truetype("arial.ttf", 28)
        font_text = ImageFont.truetype("arial.ttf", 18)
        font_small = ImageFont.truetype("arial.ttf", 14)
    except Exception:
        font_title = ImageFont.load_default()
        font_text = ImageFont.load_default()
        font_small = ImageFont.load_default()

    # まず上部にメタ情報、その下にグリッド
    padding = 24
    meta_height = 220  # タイトル & URL一覧領域（必要に応じて増減）
    bg = Image.new("RGB", (thumb_cols * (thumb_size + padding) + padding, meta_height), "white")
    d = ImageDraw.Draw(bg)

    # タイトル
    title = "Crawler Self Test Report"
    dt = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    d.text((padding, padding), title, fill="black", font=font_title)
    d.text((padding, padding + 44), f"Site: {site}", fill="black", font=font_text)
    d.text((padding, padding + 70), f"Query: {query}", fill="black", font=font_text)
    d.text((padding, padding + 96), f"Collected: {len(image_urls)} images", fill="black", font=font_text)
    d.text((padding, padding + 122), f"Generated at: {dt}", fill="black", font=font_text)

    # URL の一部を表示（長すぎると溢れるので3件まで）
    max_show = 3
    y = padding + 150
    w = bg.size[0] - padding * 2
    if image_urls:
        for i, u in enumerate(image_urls[:max_show], 1):
            # 1行に収まらない時は折返し
            lines = _text_wrap(d, f"{i}. {u}", font_small, w)
            for line in lines:
                d.text((padding, y), line, fill="gray20", font=font_small)
                y += 18
    else:
        d.text((padding, y), "(No image URLs were collected)", fill="gray30", font=font_small)

    # 画像を最大 9 枚（3x3 デフォルト）まで並べる
    max_thumbs = thumb_cols * thumb_cols
    grid_urls = image_urls[:max_thumbs]
    rows = math.ceil(len(grid_urls) / thumb_cols)
    grid_height = rows * (thumb_size + padding) + padding if rows > 0 else padding

    canvas = Image.new("RGB", (bg.size[0], bg.size[1] + grid_height), "white")
    canvas.paste(bg, (0, 0))
    d2 = ImageDraw.Draw(canvas)

    # サムネイル描画
    x0, y0 = padding, bg.size[1] + padding
    for idx, url in enumerate(grid_urls):
        col = idx % thumb_cols
        row = idx // thumb_cols
        x = padding + col * (thumb_size + padding)
        y = y0 + row * (thumb_size + padding)

        thumb = _fetch_image(url)
        if thumb is None:
            # 取得失敗時は灰色のプレースホルダ
            ph = Image.new("RGB", (thumb_size, thumb_size), "#e6e6e6")
            dph = ImageDraw.Draw(ph)
            msg = "Failed\nto load"
            wmsg, hmsg = dph.textlength("Failed", font=font_small), 2 * 18
            dph.multiline_text(((thumb_size - wmsg) / 2 - 6, (thumb_size - hmsg) / 2), msg, fill="gray40", font=font_small, align="center")
            thumb = ph
        else:
            # 余白あり縮小（サムネイル化）
            thumb.thumbnail((thumb_size, thumb_size))

            # 正方形カンバスに中央寄せ
            sq = Image.new("RGB", (thumb_size, thumb_size), "white")
            ox = (thumb_size - thumb.size[0]) // 2
            oy = (thumb_size - thumb.size[1]) // 2
            sq.paste(thumb, (ox, oy))
            thumb = sq

        canvas.paste(thumb, (x, y))
        # 枠線
        d2.rectangle([x, y, x + thumb_size, y + thumb_size], outline="lightgray", width=1)

    canvas.save(outfile, "PNG")
    return outfile


# =========================
# 自己テスト用エントリーポイント
# =========================
if __name__ == "__main__":
    from flask import Flask

    app = Flask(__name__)
    app.config.from_object(Config)
    Config.init_app(app)
    sites = app.config.get("CRAWLER_TARGET_SITES", {})

    if not sites:
        logging.error("No sites configuration found. Check config.py or crawler_sites.json.")
        raise SystemExit(1)

    test_query = os.getenv("CRAWLER_TEST_QUERY", "バッグ")
    test_site = os.getenv("CRAWLER_TEST_SITE", "farfetch")
    max_results = int(os.getenv("CRAWLER_TEST_MAX", "6"))

    crawler = CrawlerService(
        sites_config=sites,
        headless=Config.CRAWLER_HEADLESS,
        wait_time=Config.CRAWLER_DEFAULT_WAIT_TIME,
    )

    logging.info(f"[SELF-TEST] site='{test_site}', query='{test_query}', max={max_results}")
    t0 = time.time()
    try:
        urls = crawler.search_and_collect_images(site_key=test_site, query=test_query, max_results=max_results)
    except Exception as e:
        logging.exception(f"Self-test failed: {e}")
        urls = []
    t1 = time.time()

    logging.info(f"Collected {len(urls)} image URLs in {t1 - t0:.2f}s")
    for u in urls[:10]:
        logging.info(f"  - {u}")
    if len(urls) > 10:
        logging.info(f"  ... (+{len(urls) - 10} more)")

    # 画像レポートを保存
    report_dir = Path("selftest_reports")
    ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    report_file = report_dir / f"selftest_{test_site}_{ts}.png"

    try:
        outpath = save_selftest_report_png(
            report_file,
            site=test_site,
            query=test_query,
            image_urls=urls,
            thumb_cols=3,       # 3x3 グリッド
            thumb_size=256,
        )
        logging.info(f"[SELF-TEST] Report saved: {outpath.resolve()}")
    except Exception as e:
        logging.exception(f"Failed to save self-test report: {e}")
        # 画像がゼロの場合など、最低限のテキストだけでも PNG にして残す
        try:
            fallback = Image.new("RGB", (1000, 360), "white")
            d = ImageDraw.Draw(fallback)
            try:
                font = ImageFont.truetype("arial.ttf", 18)
                title = ImageFont.truetype("arial.ttf", 26)
            except Exception:
                font = ImageFont.load_default()
                title = ImageFont.load_default()
            d.text((24, 24), "Crawler Self Test Report (Fallback)", fill="black", font=title)
            d.text((24, 70), f"Site: {test_site}", fill="black", font=font)
            d.text((24, 94), f"Query: {test_query}", fill="black", font=font)
            d.text((24, 118), f"Collected: {len(urls)} images", fill="black", font=font)
            d.text((24, 142), "No image grid generated due to an error.", fill="gray35", font=font)
            report_dir.mkdir(parents=True, exist_ok=True)
            fallback.save(report_file, "PNG")
            logging.info(f"[SELF-TEST] Fallback report saved: {report_file.resolve()}")
        except Exception as ee:
            logging.exception(f"Fallback image save also failed: {ee}")
            raise

    # プロセス終了コード: 画像 0件でも成功扱い（テスト容易性のため）
    logging.info("Self-test finished.")


# --- END: atelier-kyo-manager/app\utils\ai_image_crawler.py ---


# --- START: atelier-kyo-manager/app\utils\shipping_agent.py ---

# ======================================================================
# ファイル名: shipping_agent.py
# 場所: app/utils/shipping_agent.py
# 役割: Buyandship(転送倉庫サービス)にログインして倉庫一覧を取得するエージェント。
# - 永続コンテキストで「一度ログインしたら次回以降は自動ログイン不要」
# - ログインUIは「日本語プレースホルダ/ラベル/ボタン文言」優先で堅牢化
# - セレクタ配列の段階フォールバック + パネル起動 + Cookie同意対応
# - iframeフォールバック + デバッグ用スクショ/HTML保存
# - 起動タブ選定/空白タブ除去/URLオープン再試行で about:blank 問題を回避
# 更新日: 2025-08-25
#
# --- 操作するソフト/前提 ---
# - Python 3.10 以上
# - 任意のエディタ/IDE（VS Code 推奨）
#
# --- 依存ライブラリのインストール（ターミナル） ---
# pip install "playwright==1.42.0" python-dotenv
# playwright install
#
# --- 環境変数（.env をプロジェクトルートに作成） ---
# BUYANDSHIP_EMAIL="your_email@example.com"
# BUYANDSHIP_PASSWORD="your_password"
#
# --- 初回のみ（推奨: 手動ログインでセッション保存）---
# [Windows PowerShell]
# $env:PLAYWRIGHT_HEADFUL="1"
# python -m app.utils.shipping_agent
#
# [macOS/Linux]
# PLAYWRIGHT_HEADFUL=1 python -m app.utils.shipping_agent
#
# - ブラウザが起動したら、Buyandshipにログイン（CAPTCHA/2FA対応可）。
# - 以降はヘッドレスで自動的にログイン状態が維持されます（永続プロファイル）。
#
# --- API/確認 ---
# - 例: /api/warehouses?country=HK
# ログに「メールアドレス → 次へ進む → パスワード → ログイン」の順で進行が出ればOK。
#
# --- デバッグ ---
# - 自動ログインに失敗した場合、instance/login_debug.png と instance/login_debug.html を保存。
# - 動作をゆっくりに: PLAYWRIGHT_SLOWMO=500 等を環境変数で指定。
# - ステップ実行: 一時的に $env:PWDEBUG="1" で実行 or page.pause() を挿入。
# ======================================================================
from __future__ import annotations

import os
import asyncio
import logging
import re
from typing import List, Dict, Optional

from playwright.async_api import async_playwright, Page, BrowserContext, TimeoutError as PWTimeoutError
from flask import current_app

# --- 定数定義 ---
WAREHOUSE_LIST_URL = "https://www.buyandship.co.jp/account/v2020/warehouse/"
# 永続プロファイル（セッション情報）の保存先
USER_DATA_DIR = os.path.abspath("instance/pw_profile")

# --- 追加ヘルパ（UIテキスト優先で操作。候補セレクタ配列を順に試す） ---
async def _click_first(page_or_frame, selectors: list[str], timeout_ms: int = 8000) -> bool:
    """指定されたセレクタリストに一致する最初の可視要素をクリックする"""
    for sel in selectors:
        try:
            loc = page_or_frame.locator(sel).first
            if await loc.count() > 0 and await loc.is_visible():
                await loc.click(timeout=timeout_ms)
                return True
        except Exception:
            pass
    return False

async def _fill_first(page_or_frame, selectors: list[str], text: str, timeout_ms: int = 8000) -> bool:
    """指定されたセレクタリストに一致する最初の可視要素にテキストを入力する"""
    for sel in selectors:
        try:
            loc = page_or_frame.locator(sel).first
            if await loc.count() > 0 and await loc.is_visible():
                await loc.fill(text, timeout=timeout_ms)
                return True
        except Exception:
            pass
    return False

class ShippingAgent:
    """転送倉庫の情報を取得するエージェント（Playwright, Async, 永続セッション対応, UIテキスト優先ログイン）"""

    def __init__(
        self,
        headless: Optional[bool] = None,  # None の場合は環境変数 PLAYWRIGHT_HEADFUL で制御
        state_path: str = "instance/playwright_state.json",  # デバッグ/互換用（現行は永続プロファイル優先）
        base_url: str = WAREHOUSE_LIST_URL,
        timeout_ms: int = 60_000,
    ) -> None:
        # headless の決定: 引数 > 環境変数 > デフォルト(True)
        if headless is None:
            self.headless = os.getenv("PLAYWRIGHT_HEADFUL") != "1"
        else:
            self.headless = headless

        self.state_path = state_path
        self.base_url = base_url
        self.timeout_ms = timeout_ms
        self.logger = logging.getLogger(__name__)
        self.email: Optional[str] = None
        self.password: Optional[str] = None

        # 保存先ディレクトリ作成
        os.makedirs(os.path.dirname(self.state_path) or ".", exist_ok=True)
        os.makedirs(USER_DATA_DIR, exist_ok=True)

    # ----------------------------
    # 資格情報の取得（環境変数優先）
    # ----------------------------
    def _get_credentials(self) -> Dict[str, str]:
        """
        優先度:
          1) env: BUYANDSHIP_EMAIL / BUYANDSHIP_PASSWORD
          2) Flask config: BUYANDSHIP_EMAIL / BUYANDSHIP_PASSWORD
          3) 後方互換 env/config: BNS_EMAIL / BNS_PASSWORD
        """
        email = os.getenv("BUYANDSHIP_EMAIL")
        password = os.getenv("BUYANDSHIP_PASSWORD")

        if not email or not password:
            cfg = getattr(current_app, "config", None)
            if cfg:
                email = email or cfg.get("BUYANDSHIP_EMAIL")
                password = password or cfg.get("BUYANDSHIP_PASSWORD")

        if not email:
            email = os.getenv("BNS_EMAIL") or (getattr(current_app, "config", {}) or {}).get("BNS_EMAIL")
            if email:
                self.logger.warning("Using legacy env BNS_EMAIL (rename to BUYANDSHIP_EMAIL).")
        if not password:
            password = os.getenv("BNS_PASSWORD") or (getattr(current_app, "config", {}) or {}).get("BNS_PASSWORD")
            if password:
                self.logger.warning("Using legacy env BNS_PASSWORD (rename to BUYANDSHIP_PASSWORD).")

        if not email or not password:
            raise RuntimeError("BUYANDSHIP_EMAIL / BUYANDSHIP_PASSWORD が見つかりません。.env に設定してください。")

        self.email, self.password = email, password
        return {"email": email, "password": password}

    # ----------------------------
    # 追加: 起動後に“実際に使うべきページ”を選ぶヘルパ
    # ----------------------------
    async def _pick_working_page(self, context: BrowserContext) -> Page:
        """
        永続プロファイル起動時に混在するページから、仕事に使うべき page を選ぶ（about:blank を避ける）。
        なければ新規作成して返す。
        """
        # 1) 既存タブのうち、about:blank 以外＆未クローズを優先
        for p in context.pages:
            try:
                if not p.is_closed() and p.url and not p.url.startswith("about:blank"):
                    await p.bring_to_front()
                    return p
            except Exception:
                continue

        # 2) それでも無ければ新規ページ
        page = await context.new_page()
        await page.bring_to_front()
        return page

    # ----------------------------
    # 追加: 不要な空タブを閉じる（任意）
    # ----------------------------
    async def _close_blank_tabs(self, context: BrowserContext) -> None:
        """不要な about:blank タブを閉じる"""
        # pagesリストのコピーに対してループすることで、安全にページを閉じることができる
        for p in list(context.pages):
            try:
                if not p.is_closed() and (not p.url or p.url.startswith("about:blank")):
                    await p.close()
            except Exception:
                pass

    # ----------------------------
    # 追加: URL を開く（作業ページ選択 + 再試行）
    # ----------------------------
    async def _open_target_url(self, context: BrowserContext, url: str) -> Page:
        """
        作業用ページを取得し、対象URLに遷移。
        まれに bring_to_front 直後に URL 未解決の空タブを掴むことがあるため再試行。
        """
        page = await self._pick_working_page(context)
        for _ in range(2): # 最大2回試行
            try:
                await page.goto(url, wait_until="load", timeout=self.timeout_ms)
                if page.url and not page.url.startswith("about:blank"):
                    return page
            except Exception:
                pass
            # ダメなら新しいタブで再試行
            self.logger.warning("ページの読み込みに失敗したため、新しいタブで再試行します。")
            page = await context.new_page()

        # 最終試行
        await page.goto(url, wait_until="load", timeout=self.timeout_ms)
        return page

    # ----------------------------
    # ログイン（必要時のみ）- UIテキスト優先 + 段階フォールバック + パネル起動 + 同意対応
    # ----------------------------
    async def _login_if_needed(self, page: Page, context: BrowserContext) -> None:
        """
        Buyandship ログインが必要なら行う（UI変化に強いセレクタで対応）
        """
        # 0) 既ログイン簡易チェック（見出し/ユーザーメニュー）
        try:
            if await page.locator("text=Buyandship倉庫住所一覧, text=倉庫住所一覧, text=倉庫住所").first.is_visible(timeout=3000):
                self.logger.info("既にログイン済みと判断しました。")
                return
        except Exception:
            pass
        try:
            if await page.locator("button:has-text('マイアカウント'), a:has-text('マイアカウント')").first.is_visible(timeout=2000):
                self.logger.info("既にログイン済み（ユーザーメニュー検出）と判断しました。")
                return
        except Exception:
            pass

        self.logger.info("ログインが必要です。UIテキスト優先のセレクタでログインを試みます。")

        # 1) Cookie 同意/ダイアログのクローズ
        await _click_first(page, [
            "button:has-text('同意')", "button:has-text('Accept')",
            "button[aria-label='Close']", "button.bs-cookie-consent-accept",
        ])

        # 2) ログインパネルの起動
        try:
            login_panel_open = await page.locator("input[placeholder='メールアドレス']").first.is_visible(timeout=2000)
        except Exception:
            login_panel_open = False

        if not login_panel_open:
            if await _click_first(page, [
                "a:has-text('ログイン')", "a:has-text('登録 / ログイン')",
                "button:has-text('ログイン')", "button:has-text('登録 / ログイン')",
            ]):
                await page.wait_for_timeout(500)

        # 3) メール入力
        creds = self._get_credentials()
        EMAIL_SELECTORS = [
            "input[placeholder='メールアドレス']", "input[aria-label='メールアドレス']",
            "input[type='email']", "input[name='email']", "#email, #user_email, input[id*='email']",
        ]
        await page.wait_for_timeout(300)
        if not await _fill_first(page, EMAIL_SELECTORS, creds["email"], timeout_ms=12000):
            filled_in_frame = any(await _fill_first(frame, EMAIL_SELECTORS, creds["email"], timeout_ms=8000) for frame in page.frames)
            if not filled_in_frame:
                raise RuntimeError("メール入力欄が見つかりませんでした。UIが変わっている可能性があります。")

        # 4) 「次へ進む」
        await _click_first(page, [
            "button:has-text('次へ進む')", "button:has-text('次へ')",
            "button:has-text('ログイン')", "button[type='submit']",
        ])

        # 5) パスワード入力
        PASS_SELECTORS = [
            "input[placeholder*='パスワード']", "input[aria-label*='パスワード']",
            "input[type='password']", "input[name='password']", "#password, input[id*='pass']",
        ]
        await page.wait_for_timeout(600)
        if not await _fill_first(page, PASS_SELECTORS, creds["password"], timeout_ms=15000):
            try:
                filled_in_frame = any(await _fill_first(frame, PASS_SELECTORS, creds["password"], timeout_ms=8000) for frame in page.frames)
                if not filled_in_frame:
                    raise RuntimeError("パスワード入力欄が見つかりませんでした。")
            except Exception:
                try:
                    debug_dir = os.path.dirname(self.state_path)
                    await page.screenshot(path=os.path.join(debug_dir, "login_debug.png"), full_page=True)
                    html = await page.content()
                    with open(os.path.join(debug_dir, "login_debug.html"), "w", encoding="utf-8") as f:
                        f.write(html)
                    self.logger.error(f"デバッグ情報: {os.path.join(debug_dir, 'login_debug.*')} を確認してください。")
                except Exception as e:
                    self.logger.error(f"デバッグ情報の保存中にエラー: {e}")
                raise

        # 6) 送信（ログイン）
        await _click_first(page, ["button:has-text('ログイン')", "button[type='submit']", "button:has-text('次へ')"])

        # 7) 完了待ち
        await page.wait_for_load_state("networkidle")
        await page.wait_for_timeout(800)
        try:
            if await page.locator("text=Buyandship倉庫住所一覧, text=倉庫住所").first.is_visible():
                self.logger.info("ログイン完了を検出しました。")
            else:
                self.logger.warning("ログイン完了を検出できませんでしたが処理を続行します。")
        except Exception:
            self.logger.warning("ログイン完了を検出できませんでしたが処理を続行します。")

    # ----------------------------
    # データ抽出
    # ----------------------------
    async def _extract_warehouses(self, page: Page, country_code: str) -> List[Dict]:
        """倉庫カード要素から情報を抽出する。"""
        warehouses: List[Dict] = []
        card_sel = "div.warehouse-card, article.warehouse, li.warehouse, div[class*='warehouse-item']"
        cards = page.locator(card_sel)
        count = await cards.count()
        self.logger.info(f"'{country_code}' の倉庫カード候補要素数: {count}")
        for i in range(count):
            card = cards.nth(i)
            country_text = ""
            for sel in [".country-name", '[data-testid="country"]', ".warehouse-country"]:
                if await card.locator(sel).count() > 0:
                    country_text = (await card.locator(sel).first.inner_text()).strip()
                    break
            if country_code.upper() not in country_text.upper():
                continue
            name = (await card.locator("h3, .warehouse-name").first.inner_text()).strip()
            address = (await card.locator("address, [class*='address-detail']").first.inner_text()).strip()
            fee = None
            if await card.locator(".warehouse-fee").count() > 0:
                raw = (await card.locator(".warehouse-fee").first.inner_text()).strip()
                m = re.search(r"(\d+(?:\.\d+)?)", raw.replace(",", ""))
                if m:
                    fee = float(m.group(1))
            if name and address:
                warehouses.append({"name": name, "address": address, "country": country_code.upper(), "fee": fee})
        return warehouses

    # ----------------------------
    # メイン処理（非同期）- 永続セッション対応
    # ----------------------------
    async def _get_warehouses_async(self, country_code: str = "US") -> List[Dict]:
        """永続コンテキストを使用してブラウザを起動し、倉庫情報を取得する。"""
        self.logger.info(f"{country_code} の倉庫情報取得を開始します (Headless: {self.headless})...")
        self.logger.info(f"ユーザープロファイル: {USER_DATA_DIR}")
        async with async_playwright() as p:
            context = None
            try:
                context = await p.chromium.launch_persistent_context(
                    USER_DATA_DIR,
                    headless=self.headless,
                    slow_mo=int(os.getenv("PLAYWRIGHT_SLOWMO", "0") or 0),
                    channel="chrome",
                    args=["--restore-last-session", "--no-first-run", "--no-default-browser-check", "--disable-session-crashed-bubble"],
                )
                await self._close_blank_tabs(context)
                page = await self._open_target_url(context, self.base_url)
                page.set_default_timeout(self.timeout_ms)
                await self._login_if_needed(page, context)
                if self.base_url not in page.url:
                    self.logger.info("再度、倉庫ページへアクセスします。")
                    page = await self._open_target_url(context, self.base_url)
                data = await self._extract_warehouses(page, country_code=country_code.upper())
                if not data:
                    self.logger.warning(f"{country_code} の倉庫情報が抽出できませんでした。")
                else:
                    self.logger.info(f"{len(data)}件の倉庫情報を取得しました。")
                return data
            except Exception as e:
                self.logger.error(f"Playwright操作中にエラーが発生しました: {e}", exc_info=True)
                return []
            finally:
                if context:
                    await context.close()
                self.logger.info("ブラウザセッションを終了しました。")

    # ----------------------------
    # 同期ラッパー
    # ----------------------------
    def get_warehouses_by_country(self, country_code: str = "US") -> List[Dict]:
        """Flaskなどから同期的に呼び出すためのラッパー関数"""
        return asyncio.run(self._get_warehouses_async(country_code))

    def fetch_warehouses(self, country_code: str) -> List[Dict]:
        """get_warehouses_by_country のエイリアス"""
        return self.get_warehouses_by_country(country_code)

# --- 単体実行テスト ---
if __name__ == "__main__":
    try:
        from dotenv import load_dotenv
        load_dotenv()
        print(".envファイルを読み込みました。")
    except ImportError:
        print("python-dotenvが未インストールのため、.envファイルは読み込まれません。")

    logging.basicConfig(level=logging.INFO, format="[%(asctime)s] %(levelname)s:%(name)s:%(message)s")

    # headless=None にすると環境変数(PLAYWRIGHT_HEADFUL)で制御
    agent = ShippingAgent(headless=None)

    print("\n--- アメリカ(US)の倉庫情報を取得 ---")
    us_result = agent.get_warehouses_by_country("US")
    print(us_result)

    print("\n--- 香港(HK)の倉庫情報を取得 ---")
    hk_result = agent.get_warehouses_by_country("HK")
    print(hk_result)

    print("\n--- イギリス(UK)の倉庫情報を取得 ---")
    uk_result = agent.get_warehouses_by_country("UK")
    print(uk_result)


# --- END: atelier-kyo-manager/app\utils\shipping_agent.py ---


